\set ON_ERROR_STOP on
do $$begin if current_database()<>'byus_clean'or inet_server_addr()is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;end $$;
begin;
create function pg_temp.proof_assert(ok boolean,message text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',message;end if;raise notice 'PASS %',message;end $$;
create function pg_temp.proof_error(statement text,expected text)returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;end if;raise;end;raise exception 'Expected %',expected;end $$;
do $$declare owner uuid:=gen_random_uuid();member uuid:=gen_random_uuid();manager2 uuid:=gen_random_uuid();other uuid:=gen_random_uuid();page uuid:=gen_random_uuid();photo uuid:=gen_random_uuid();survey uuid:=gen_random_uuid();plain uuid:=gen_random_uuid();event uuid:=gen_random_uuid();registration uuid:=gen_random_uuid();images uuid[];image uuid;submission uuid;result jsonb;input jsonb;stale jsonb;before_counts jsonb;after_counts jsonb;legacy_submission uuid:=gen_random_uuid();legacy_request uuid:=gen_random_uuid();legacy_input jsonb;legacy_receipt jsonb;begin
 insert into public.app_users(id,privy_user_id,verified_email)select x,'activity-proof-'||x,x||'@example.test'from unnest(array[owner,member,manager2,other])x;
 insert into public.group_pages(id,kind,name)values(page,'hobby','Evidence fixture');
 insert into public.group_memberships(page_id,app_user_id,role)values(page,owner,'owner'),(page,member,'member'),(page,manager2,'manager'),(page,other,'member');
 update public.group_wallet_release set enabled=true,write_fenced=false,legacy_writers_verified=true,migration_evidence_sha256=repeat('a',64),rewards_start_on=current_date;
 images:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 insert into public.mobile_media_assets(id,app_user_id,kind,purpose,content_type,expected_byte_size,actual_byte_size,storage_path,thumbnail_path,state,width,height,request_id,request_hash)select x,member,'image','group_image','image/png',100,100,'private/'||x||'.png','private/'||x||'.webp','ready',20,20,gen_random_uuid(),'fixture'from unnest(images)x;
 insert into public.group_missions(id,page_id,title,instructions,state,submission_kind,survey_question,survey_options)values(photo,page,'Photo mission','Original photograph','published','photo',null,null),(survey,page,'Survey mission','Choose one','published','survey','Original question','["First","Second","Third"]'),(plain,page,'Text mission','Text only','published','text',null,null);
 input:=jsonb_build_object('requestId',gen_random_uuid(),'body','My original description','imageAssetId',images[1],'originalAttested',true,'expectedMissionRevision',1);
 result:=public.group_activities_dispatch('mission-submit',member,page,photo,null,input);submission:=(result->>'id')::uuid;
 perform pg_temp.proof_assert(result=public.group_activities_dispatch('mission-submit',member,page,photo,null,input)and(select count(*)from public.group_activity_evidence where target_id=submission)=1,'photo receipt replay preserves one exact evidence revision');
 perform pg_temp.proof_assert(result->>'imageAssetId'=images[1]::text and(result->>'currentRevision')::integer=1,'submit receipt includes persisted image and current revision');
 perform pg_temp.proof_assert(public.authorize_group_image_read(null,images[1],'original')is null and public.authorize_mobile_media_read(other,images[1],'thumbnail')is null and public.authorize_mobile_media_read(member,images[1],'original')is not null and public.authorize_mobile_media_read(owner,images[1],'thumbnail')is not null,'both original/thumbnail entrypoints enforce private proof ACL');
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-submit'',%L,%L,%L,null,%L)',member,page,photo,input||jsonb_build_object('imageAssetId',images[2])),'CONFLICT');
 stale:=jsonb_build_object('requestId',gen_random_uuid(),'expectedSubmissionRevision',1,'action','approve');
 perform public.group_activities_dispatch('mission-review',manager2,page,photo,submission,jsonb_build_object('requestId',gen_random_uuid(),'expectedSubmissionRevision',1,'action','reject','reason','Need a clearer picture'));
 input:=input||jsonb_build_object('requestId',gen_random_uuid(),'expectedSubmissionRevision',1,'imageAssetId',images[2],'body','Second original description');
 result:=public.group_activities_dispatch('mission-submit',member,page,photo,null,input);
 select jsonb_build_array((select count(*)from public.group_activity_receipts),(select count(*)from public.group_mission_submission_reviews),(select count(*)from public.group_activity_evidence),(select count(*)from public.mobile_fan_economy_ledger))into before_counts;
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-review'',%L,%L,%L,%L,%L)',owner,page,photo,submission,stale),'CONFLICT');
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-review'',%L,%L,%L,%L,%L)',owner,page,photo,submission,stale||jsonb_build_object('action','reject','reason','Stale rejection')),'CONFLICT');
 select jsonb_build_array((select count(*)from public.group_activity_receipts),(select count(*)from public.group_mission_submission_reviews),(select count(*)from public.group_activity_evidence),(select count(*)from public.mobile_fan_economy_ledger))into after_counts;
 perform pg_temp.proof_assert(before_counts=after_counts and(select current_revision=2 and status='pending'from public.group_mission_submissions where id=submission),'stale approve/reject changes no receipt, evidence, history or ledger');
 perform pg_temp.proof_assert((select count(*)from public.group_mission_submission_revisions where submission_id=submission)=2 and(select state='ready'from public.mobile_media_assets where id=images[1]),'resubmission preserves original immutable description and photo');
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-review'',%L,%L,%L,%L,%L)',owner,page,photo,submission,jsonb_build_object('requestId',gen_random_uuid(),'action','approve')),'CONFLICT');
 perform public.group_activities_dispatch('mission-review',owner,page,photo,submission,jsonb_build_object('requestId',gen_random_uuid(),'expectedSubmissionRevision',2,'action','reject','reason','Change submission type'));
 update public.group_missions set submission_kind='text',revision=2 where id=photo;
 result:=public.group_activities_dispatch('mission-submit',member,page,photo,null,jsonb_build_object('requestId',gen_random_uuid(),'body','Original text after type change','expectedSubmissionRevision',2));
 perform pg_temp.proof_assert(result->>'imageUrl'is null and(select evidence_id is null from public.group_mission_submissions where id=submission)and(select count(*)from public.group_activity_evidence where target_id=submission)=2 and(select state='ready'from public.mobile_media_assets where id=images[2]),'type change clears current proof while immutable previous photos remain available');

 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-submit'',%L,%L,%L,null,%L)',other,page,photo,input||jsonb_build_object('requestId',gen_random_uuid(),'imageAssetId',images[3])),'INVALID');
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-submit'',%L,%L,%L,null,%L)',other,page,photo,input||jsonb_build_object('requestId',gen_random_uuid(),'imageAssetId',null,'originalAttested',false)),'INVALID');
 input:=jsonb_build_object('requestId',gen_random_uuid(),'body','','surveyChoice',1,'expectedMissionRevision',1);
 result:=public.group_activities_dispatch('mission-submit',member,page,survey,null,input);
 perform pg_temp.proof_assert(result->>'body'=''and result#>>'{surveyResponse,choiceLabel}'='Second'and result#>>'{surveyResponse,opinion}'='','survey stores blank original opinion separately from selected persisted label');
 update public.group_missions set survey_question='Edited question',survey_options='["New first","New second","New third"]',revision=2 where id=survey;
 perform pg_temp.proof_assert((select survey_response->>'question'='Original question'and survey_response->>'choiceLabel'='Second'from public.group_mission_submission_revisions where submission_id=(result->>'id')::uuid),'later mission edits cannot reinterpret saved survey choices');
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-submit'',%L,%L,%L,null,%L)',other,page,survey,input||jsonb_build_object('requestId',gen_random_uuid())),'CONFLICT');
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-submit'',%L,%L,%L,null,%L)',other,page,survey,input||jsonb_build_object('requestId',gen_random_uuid(),'surveyChoice',3,'expectedMissionRevision',2)),'INVALID');
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''mission-submit'',%L,%L,%L,null,%L)',other,page,survey,input||jsonb_build_object('requestId',gen_random_uuid(),'imageAssetId',images[3],'expectedMissionRevision',2)),'INVALID');
 result:=public.group_activities_dispatch('mission-submit',member,page,plain,null,jsonb_build_object('requestId',gen_random_uuid(),'body','Legacy original text'));
 perform pg_temp.proof_assert(result->>'body'='Legacy original text','legacy text submit remains compatible');
 insert into public.group_mission_submissions(id,mission_id,app_user_id,body,status)values(legacy_submission,plain,other,'Pre-upgrade original text','completed');
 insert into public.group_mission_submission_revisions(submission_id,revision,body,original_attested)values(legacy_submission,1,'Pre-upgrade original text',false);
 legacy_input:=jsonb_build_object('requestId',legacy_request,'action','approve','reason','');legacy_receipt:=jsonb_build_object('id',legacy_submission,'status','completed','rewardPoints',0);
 insert into public.group_activity_receipts(actor_id,request_id,operation,payload,response)values(owner,legacy_request,'mission-review',jsonb_build_object('pageId',page,'itemId',plain,'subId',legacy_submission,'input',legacy_input),legacy_receipt);
 perform pg_temp.proof_assert(public.group_activities_dispatch('mission-review',owner,page,plain,legacy_submission,legacy_input)=legacy_receipt,'exact pre-upgrade review receipt replays without a revision field');

 insert into public.group_events(id,page_id,title,description,starts_at,ends_at,opens_at,closes_at,location,state,created_by)values(event,page,'Finished event','Original event',now()-interval'2 days',now()-interval'1 day',now()-interval'4 days',now()-interval'3 days','Seoul','ended',owner);
 insert into public.group_event_registrations(id,event_id,app_user_id,status,checked_in_at)values(registration,event,member,'confirmed',now()-interval'2 days');
 input:=jsonb_build_object('requestId',gen_random_uuid(),'title','My original title','body','My original event review','imageAssetId',images[3]);
 result:=public.group_activities_dispatch('event-review-write',member,page,event,null,input);
 perform pg_temp.proof_assert(result=public.group_activities_dispatch('event-review-write',member,page,event,null,input)and result#>>'{review,title}'='My original title','event review title/photo and receipt committed atomically');
 perform pg_temp.proof_assert(public.authorize_mobile_media_read(other,images[3],'original')is null and public.authorize_mobile_media_read(owner,images[3],'original')is not null,'review photo remains private to author and reviewers');
 input:=input||jsonb_build_object('requestId',gen_random_uuid(),'expectedReviewRevision',1,'title','Edited title','imageAssetId',images[4]);
 perform public.group_activities_dispatch('event-review-write',member,page,event,null,input);
 perform pg_temp.proof_error(format('select public.group_activities_dispatch(''event-review-write'',%L,%L,%L,null,%L)',member,page,event,input||jsonb_build_object('requestId',gen_random_uuid())),'CONFLICT');
 perform pg_temp.proof_assert((select count(*)from public.group_event_review_revisions where registration_id=registration)=2 and(select state='ready'from public.mobile_media_assets where id=images[3]),'event review edits preserve old title/body/photo');
 perform pg_temp.proof_assert(not has_table_privilege('service_role','public.group_activity_evidence','SELECT')and not has_function_privilege('service_role','public.group_attach_activity_evidence(uuid,text,uuid,uuid)','EXECUTE'),'raw evidence and attachment helper stay private');
end $$;
rollback;
